head.script:
scwin.onpageload = function() {
	// editor1.setReadOnly(true);
    var html = '<div>네이버</div>'
    html += '<a href="https://kstaplus.ksnet.co.kr" target="_blank">바로가기기</a>'

    editor1.setHTML(html);
};


// 가설1 : a태그 onclick 시 return false가 들어가있다.
// 가설2 : 다른 태그와 곂침
// 가설3 : 링크가 잘못되었다. x

scwin.trigger1_onclick = function(e) {
    editor1.setDisabled(true);
};

scwin.trigger2_onclick = function(e) {
    editor1.setDisabled(false);
};

    scwin.checkVal = function() {
        let elements = WebSquare.wUnit.getDomById('editor1_disabled_div');

        return elements !== null;
    };

    scwin.unitTest = function () {
        //Unit 
        WebSquare.wUnit.start();
        WebSquare.wUnit.addCommand("pause", "500");
        WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('ck-button')[0].click()");
        WebSquare.wUnit.addCommand("pause", "500");
        WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
        WebSquare.wUnit.addCommand("pause", "500");
        WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
        WebSquare.wUnit.addCommand("pause", "500");

        //Run test and stop
        WebSquare.wUnit.run();
        WebSquare.wUnit.stop();
    };

    scwin.unitTest();
